public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        String pwd = r.next(), target = r.next();
        long[] cost = new long[26], have = new long[26], need = new long[26];
        for (int i = 0; i < 26; i++) cost[i] = r.nextLong();
        for (int i = 0; i < pwd.length(); i++) have[pwd.charAt(i) - 'a']++;
        for (int i = 0; i < target.length(); i++) need[target.charAt(i) - 'a']++;
        long ans = Long.MAX_VALUE;
        for (int c = 0; c < 26; c++)
            if (need[c] > 0) ans = Math.min(ans, Math.max(0, have[c] - need[c] + 1) * cost[c]);
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	pwd, target := readToken(), readToken()
	var cost, have, need [26]int
	for i := range cost {
		cost[i] = readInt()
	}
	for i := 0; i < len(pwd); i++ {
		have[pwd[i]-'a']++
	}
	for i := 0; i < len(target); i++ {
		need[target[i]-'a']++
	}
	ans := -1
	for c := 0; c < 26; c++ {
		if need[c] > 0 {
			v := max(0, have[c]-need[c]+1) * cost[c]
			if ans < 0 || v < ans {
				ans = v
			}
		}
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
